import static com.ruoyi.medical.persistence.ProfessionalCheckService.*;

/** DC05 immutable human decisions with per-field CAS and original-operation recovery. */
public final class StrictFieldHumanService {
 private final SharedFactConsumptionAuthority facts;private final HumanEvidenceReviewService humans;private final EnterpriseAccess access;private final JdbcTemplate db;private final DocumentReadService documents;private final ResourceReadAuthority resources;private final StrictFieldHumanBasis basis;private final StrictFieldHumanSchema schema;
 private final TaskSourceVerifierSchema json=new TaskSourceVerifierSchema();
 public StrictFieldHumanService(DataSource data,EnterpriseAccess access,DocumentReadService documents,ResourceReadAuthority resources,StrictFieldHumanBasis basis,StrictFieldHumanSchema schema,HumanEvidenceReviewService humans,SharedFactConsumptionAuthority facts){this.facts=facts;this.humans=humans;this.access=access;db=new JdbcTemplate(data);db.setQueryTimeout(5);this.documents=documents;this.resources=resources;this.basis=basis;this.schema=schema;}
 public JsonNode basis(ApplicationSessionIdentity.Verified subject,String context,StrictFieldHumanBasis.Target target)throws Exception{var verified=basis.prepare(subject,context,target);return tx(subject,a->{var current=verified.current(a,context);return json.tree(Map.of("schema_version","1.0.0","baseline",current.witness(),"baseline_sha256",json.hash(current.witness()),"expected_revision",revision(verified),"machine_approval",false));});}
 public JsonNode decide(ApplicationSessionIdentity.Verified subject,String context,String document,String key,byte[] bytes)throws Exception {
  SimulationInputArtifactSchema.key(key);var request=schema.request(bytes);if(text(request,"reason").isBlank()||!request.required("question").isNull()&&text(request,"question").isBlank())throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);
  var target=target(document,request);String hash=json.hash(Map.of("document_id",document,"request",request));var proof=documents.readFixed(subject,context,document,target.revision());
  var replay=tx(subject,a->{authorize(a,context,proof);return recover(a,document,key,hash);});if(replay!=null)return replay;
  var verified=basis.prepare(subject,context,target);
  return tx(subject,a->{authorize(a,context,verified.document);var prior=recover(a,document,key,hash);if(prior!=null)return prior;var current=verified.current(a,context);String decision=text(request,"decision");
   if(!"REQUEST_EVIDENCE".equals(decision))requireCheckCurrent(a,verified);StrictFieldHumanBasis.requireDecision(verified,current,decision);
   if(!text(request,"expected_revision").equals(revision(verified)))throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
   if(!text(request,"baseline_sha256").equals(json.hash(current.witness())))throw new TenantAccessException(ErrorCode.REVIEW_STALE);
   var h=verified.document.header();if("SIGNED".equals(h.status()))throw new TenantAccessException(ErrorCode.REVIEW_STALE);String id=id(),op=id(),audit=id(),event=id(),next=PermissionSchema.next(text(request,"expected_revision"));LocalDateTime at=Objects.requireNonNull(db.queryForObject("SELECT UTC_TIMESTAMP(6)",LocalDateTime.class));
   var receipt=(ObjectNode)json.tree(Map.of("schema_version","1.0.0","decision_id",id,"document_id",document,"document_revision",h.documentRevision(),"field_id",target.field(),"decision",decision,"revision",next,"actor_id",a.actorId(),"created_at",at.toInstant(java.time.ZoneOffset.UTC).toString()));receipt.set("row_id",request.required("row_id"));receipt.put("baseline_sha256",text(request,"baseline_sha256")).put("reason",text(request,"reason")).put("operation_id",op).put("audit_id",audit).put("event_id",event);receipt.set("question",request.required("question"));receipt.put("state",switch(decision){case "CONFIRM"->"CONFIRMED";case "NOT_APPLICABLE"->"NOT_APPLICABLE";default->"AWAITING_EVIDENCE";});
   schema.result("Receipt",receipt);
   insert("version_registry",Map.of("tenant_id",h.tenantId(),"owner_project_id",h.projectId(),"version_id",id,"entity_kind","STRICT_FIELD_HUMAN_DECISION","content_sha256",json.hash(receipt)));
   var operation=meta(a,h,at);operation.remove("project_id");operation.putAll(Map.of("operation_id",op,"subject_id",a.actorId(),"operation_name","DC-05","idempotency_key",key,"request_sha256",hash,"state","COMPLETED","http_status",201,"response_ref",json.canonical(receipt),"target_id",document,"revision",1));operation.put("updated_at",at);insert("operation_record",operation);
   var saved=meta(a,h,at);saved.putAll(Map.of("decision_id",id,"document_id",document,"document_revision",h.documentRevision(),"field_id",target.field(),"row_key",target.row()==null?"SCALAR":target.row(),"actor_id",a.actorId(),"operation_id",op,"idempotency_key",key,"request_sha256",hash,"request_json",json.canonical(request)));saved.putAll(Map.of("baseline_json",json.canonical(current.witness()),"baseline_sha256",json.hash(current.witness()),"receipt_json",json.canonical(receipt),"receipt_sha256",json.hash(receipt),"revision",next,"auth_epoch",a.context().auth_epoch(),"governance_epoch",a.context().governance_epoch()));insert("strict_field_human_decision",saved);
   if("1".equals(next)){var head=meta(a,h,at);head.putAll(Map.of("document_revision",h.documentRevision(),"field_id",target.field(),"row_key",target.row()==null?"SCALAR":target.row(),"revision",next,"decision_id",id));insert("strict_field_human_head",head);}else if(db.update("UPDATE strict_field_human_head SET revision=?,decision_id=? WHERE tenant_id=? AND project_id=? AND document_revision=? AND field_id=? AND row_key=? AND revision=?",next,id,h.tenantId(),h.projectId(),h.documentRevision(),target.field(),target.row()==null?"SCALAR":target.row(),text(request,"expected_revision"))!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
   var log=meta(a,h,at);log.putAll(Map.of("audit_id",audit,"subject_id",a.actorId(),"action","field.human_decision.recorded","resource_ref",json.canonical(receipt),"result","SUCCESS","request_id",op,"trace_id",op));insert("audit_event",log);insert("outbox_event",Map.of("tenant_id",h.tenantId(),"event_id",event,"aggregate_id",id,"aggregate_revision",next,"event_type","field.human_decision.recorded","payload",json.canonical(receipt),"occurred_at",at));
   // A question is a genuine open task for the requester, never synthesized source evidence.
   if("REQUEST_EVIDENCE".equals(decision)){var q=meta(a,h,at);q.putAll(Map.of("question_id",id,"decision_id",id,"document_revision",h.documentRevision(),"question",text(request,"question"),"assignee_id",a.actorId(),"status","OPEN"));insert("strict_field_evidence_question",q);}
   for(String parent:List.of(h.documentRevision(),str(verified.check.snapshot().row(),"findings_artifact_id")))insert("lineage_edge",Map.of("tenant_id",h.tenantId(),"consumer_version_id",id,"upstream_version_id",parent,"relation_kind","STRICT_FIELD_HUMAN_INPUT","actor_id",a.actorId(),"created_at",at));
   db.update("INSERT INTO review_invalidation(tenant_id,project_id,invalidation_id,review_id,trigger_version,reason_code,created_by,created_at,classification) SELECT tenant_id,project_id,UUID(),review_id,?,'FIELD_DECISION_CHANGED',?,?,classification FROM review_decision WHERE tenant_id=? AND project_id=? AND document_revision=? AND decision='CONFIRM'",id,a.actorId(),at,h.tenantId(),h.projectId(),h.documentRevision());
   return receipt;
  });
 }
 /** Public history read rechecks current authorization, then reports invalidity without reviving older decisions. */
 public JsonNode read(ApplicationSessionIdentity.Verified subject,String context,String document,String id)throws Exception {
  WireValues.uuid(id);var identity=tx(subject,a->{StrictComparisonAuthority.human(a,context);return one(db.queryForList("SELECT document_revision FROM strict_field_human_decision WHERE tenant_id=? AND document_id=? AND decision_id=? FOR UPDATE",a.context().tenant_id(),document,id));});
  var proof=documents.readFixed(subject,context,document,str(identity,"document_revision"));var row=tx(subject,a->{authorize(a,context,proof);return original(a,document,id);});var request=json.read(str(row,"request_json"));String invalid=null;
  try{var v=basis.prepare(subject,context,target(document,request));tx(subject,a->{var current=v.current(a,context);if(!json.hash(current.witness()).equals(str(row,"baseline_sha256"))||!str(row,"revision").equals(revision(v)))throw new TenantAccessException(ErrorCode.REVIEW_STALE);if(!a.context().auth_epoch().equals(str(row,"auth_epoch"))||!a.context().governance_epoch().equals(str(row,"governance_epoch")))throw new TenantAccessException(ErrorCode.REVIEW_STALE);if(!"REQUEST_EVIDENCE".equals(text(request,"decision")))requireCheckCurrent(a,v);StrictFieldHumanBasis.requireDecision(v,current,text(request,"decision"));return null;});}
  catch(TenantAccessException e){if(e.code()==ErrorCode.ACCESS_DENIED||e.code()==ErrorCode.DEPENDENCY_UNAVAILABLE)throw e;invalid=e.code().name();}
  var view=(ObjectNode)json.tree(Map.of("schema_version","1.0.0","receipt",json.read(str(row,"receipt_json")),"valid",invalid==null));if(invalid==null)view.putNull("invalidation_reason");else view.put("invalidation_reason",invalid);schema.result("History",view);return view;
 }
 public JsonNode questions(ApplicationSessionIdentity.Verified subject,String context,String document,String revision)throws Exception{var proof=documents.readFixed(subject,context,document,revision);return tx(subject,a->{authorize(a,context,proof);var h=proof.header();var result=db.queryForList("SELECT q.question_id,q.decision_id,q.question,q.assignee_id,q.created_at,CASE WHEN head.decision_id=q.decision_id THEN 'OPEN' ELSE 'SUPERSEDED' END AS effective_status FROM strict_field_evidence_question q JOIN strict_field_human_decision d ON d.tenant_id=q.tenant_id AND d.project_id=q.project_id AND d.decision_id=q.decision_id JOIN strict_field_human_head head ON head.tenant_id=d.tenant_id AND head.project_id=d.project_id AND head.document_revision=d.document_revision AND head.field_id=d.field_id AND head.row_key=d.row_key WHERE q.tenant_id=? AND q.project_id=? AND q.document_revision=? ORDER BY q.created_at,q.question_id LIMIT 1001 FOR UPDATE",h.tenantId(),h.projectId(),revision);var items=json.tree(result.stream().map(r->{var copy=new LinkedHashMap<>(r);copy.put("created_at",r.get("created_at").toString());return copy;}).toList());if(items.size()>1000)throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);return json.tree(Map.of("schema_version","1.0.0","document_revision",revision,"items",items,"evidence",false));});}
 /** Formal-review consumer; preparation performs physical reads outside the transaction. */
 public Confirmed prepareConfirmed(ApplicationSessionIdentity.Verified subject,String context,DocumentReadService.FixedRead proof)throws Exception {
  var rows=tx(subject,a->{authorize(a,context,proof);var h=proof.header();return db.queryForList("SELECT f.field_id,f.row_key,h.decision_id FROM field_value f LEFT JOIN strict_field_human_head h ON h.tenant_id=f.tenant_id AND h.project_id=f.project_id AND h.document_revision=f.document_revision AND h.field_id=f.field_id AND h.row_key=f.row_key WHERE f.tenant_id=? AND f.project_id=? AND f.document_revision=? ORDER BY f.field_id,f.row_key FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision());});
  var decisions=new ArrayList<DecisionProof>();for(var row:rows){if(row.get("decision_id")==null)throw new TenantAccessException(ErrorCode.REVIEW_STALE);var original=tx(subject,a->{authorize(a,context,proof);return original(a,proof.header().documentId(),str(row,"decision_id"));});var request=json.read(str(original,"request_json"));if("REQUEST_EVIDENCE".equals(text(request,"decision")))throw new TenantAccessException(ErrorCode.REVIEW_STALE);var verified=basis.prepare(subject,context,target(proof.header().documentId(),request));decisions.add(new DecisionProof(verified,original));}
  var confirmed=new Confirmed(context,proof,List.copyOf(decisions));return tx(subject,a->{confirmed.requireCurrent(a);return confirmed;});
 }
 private record DecisionProof(StrictFieldHumanBasis.Verified basis,Map<String,Object> row){}
 public final class Confirmed {
  private final String context;private final DocumentReadService.FixedRead document;private final List<DecisionProof> decisions;
  private Confirmed(String context,DocumentReadService.FixedRead document,List<DecisionProof> decisions){this.context=context;this.document=document;this.decisions=decisions;}
  public JsonNode witness()throws Exception{var entries=new ArrayList<JsonNode>();for(var p:decisions)entries.add(json.read(str(p.row(),"receipt_json")));return json.tree(Map.of("document_revision",document.header().documentRevision(),"body_sha256",document.header().bodySha256(),"decisions",entries));}
  public void requireCurrent(EnterpriseAccess.Admission a)throws Exception{
   authorize(a,context,document);var h=document.header();var physical=db.queryForList("SELECT field_id,row_key FROM field_value WHERE tenant_id=? AND project_id=? AND document_revision=? ORDER BY field_id,row_key FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision());if(physical.size()!=decisions.size())throw new TenantAccessException(ErrorCode.REVIEW_STALE);
   for(var p:decisions){var v=p.basis();var row=original(a,h.documentId(),str(p.row(),"decision_id"));same(row,p.row());var state=v.current(a,context);requireCheckCurrent(a,v);var request=json.read(str(row,"request_json"));StrictFieldHumanBasis.requireDecision(v,state,text(request,"decision"));
    if(!str(row,"baseline_sha256").equals(json.hash(state.witness()))||!str(row,"revision").equals(revision(v))||!a.context().auth_epoch().equals(str(row,"auth_epoch"))||!a.context().governance_epoch().equals(str(row,"governance_epoch")))throw new TenantAccessException(ErrorCode.REVIEW_STALE);
   }
  }
 }
 private void requireCheckCurrent(EnterpriseAccess.Admission a,StrictFieldHumanBasis.Verified v)throws Exception{
  var actual=one(v.document.body().fields().stream().filter(f->f.fieldId().equals(v.target.field())).toList());for(var usage:v.document.body().factUsages())if(usage.fieldIds().contains(actual.fieldId())||usage.nodeIds().contains(actual.nodeId()))facts.requireConsumable(a,v.document.header().projectId(),usage.factVersionId());
  if(v.check.invalidation()==null){v.check.requireValid(a);return;}
  var batch=humans.requireCurrentBatch(a,v.document);v.check.requireValidForHumanEvidence(a,batch);
  var field=one(v.document.body().fields().stream().filter(f->f.fieldId().equals(v.target.field())).toList());
  for(var item:batch.decisions()){var decision=item.required("decision");if(field.evidenceLinkIds().contains(text(decision,"evidence_link_id"))&&(!"PASS".equals(text(decision,"access"))||!"PASS".equals(text(decision,"location"))||!("NOT_APPLICABLE".equals(v.initial.applicability().status())?"NOT_APPLICABLE":"SUPPORTED").equals(text(decision,"support"))))throw new TenantAccessException(ErrorCode.REVIEW_STALE);}
 }
 private JsonNode recover(EnterpriseAccess.Admission a,String document,String key,String hash)throws Exception{var rows=db.queryForList("SELECT decision_id,document_id,request_sha256 FROM strict_field_human_decision WHERE tenant_id=? AND actor_id=? AND idempotency_key=? FOR UPDATE",a.context().tenant_id(),a.actorId(),key);if(rows.isEmpty())return null;var row=one(rows);if(!document.equals(str(row,"document_id"))||!hash.equals(str(row,"request_sha256")))throw new TenantAccessException(ErrorCode.IDEMPOTENCY_CONFLICT);return json.read(str(original(a,document,str(row,"decision_id")),"receipt_json"));}
 private Map<String,Object> original(EnterpriseAccess.Admission a,String document,String id)throws Exception{var row=one(db.queryForList("SELECT * FROM strict_field_human_decision WHERE tenant_id=? AND document_id=? AND decision_id=? FOR UPDATE",a.context().tenant_id(),document,id));same(schema.manifest(),str(row,"schema_manifest_sha256"));var receipt=json.read(str(row,"receipt_json"));schema.result("Receipt",receipt);same("1.0.0",str(row,"schema_version"));same(str(row,"actor_id"),str(row,"created_by"));for(String name:List.of("decision_id","document_id","document_revision","field_id","revision","actor_id","operation_id","baseline_sha256"))same(str(row,name),text(receipt,name));same(str(row,"row_key"),receipt.required("row_id").isNull()?"SCALAR":text(receipt,"row_id"));var registry=one(db.queryForList("SELECT owner_project_id,entity_kind,content_sha256 FROM version_registry WHERE tenant_id=? AND version_id=? FOR UPDATE",a.context().tenant_id(),id));same(str(row,"project_id"),str(registry,"owner_project_id"));same("STRICT_FIELD_HUMAN_DECISION",str(registry,"entity_kind"));same(str(row,"receipt_sha256"),str(registry,"content_sha256"));same(json.hash(receipt),str(row,"receipt_sha256"));same(json.hash(json.read(str(row,"baseline_json"))),str(row,"baseline_sha256"));same(json.hash(Map.of("document_id",document,"request",json.read(str(row,"request_json")))),str(row,"request_sha256"));same(receipt,json.read(str(one(db.queryForList("SELECT response_ref FROM operation_record WHERE tenant_id=? AND operation_id=? AND operation_name='DC-05' AND state='COMPLETED' AND request_sha256=? AND subject_id=? FOR UPDATE",a.context().tenant_id(),str(row,"operation_id"),str(row,"request_sha256"),str(row,"actor_id"))),"response_ref")));same(receipt,json.read(str(one(db.queryForList("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND audit_id=? AND subject_id=? AND action='field.human_decision.recorded' AND result='SUCCESS' FOR UPDATE",a.context().tenant_id(),text(receipt,"audit_id"),str(row,"actor_id"))),"resource_ref")));same(receipt,json.read(str(one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND event_type='field.human_decision.recorded' FOR UPDATE",a.context().tenant_id(),text(receipt,"event_id"),id)),"payload")));return row;}
 private String revision(StrictFieldHumanBasis.Verified v){var h=v.document.header();var rows=db.queryForList("SELECT h.revision FROM strict_field_human_head h JOIN strict_field_human_decision d ON d.tenant_id=h.tenant_id AND d.project_id=h.project_id AND d.decision_id=h.decision_id AND d.document_revision=h.document_revision AND d.field_id=h.field_id AND d.row_key=h.row_key AND d.revision=h.revision WHERE h.tenant_id=? AND h.project_id=? AND h.document_revision=? AND h.field_id=? AND h.row_key=? FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision(),v.target.field(),v.target.row()==null?"SCALAR":v.target.row());return rows.isEmpty()?"0":str(one(rows),"revision");}
 private void authorize(EnterpriseAccess.Admission a,String context,DocumentReadService.FixedRead p)throws Exception{StrictComparisonAuthority.human(a,context);documents.requireCurrent(a,p);var h=p.header();resources.require(a,new PermissionProtocol.Scope(h.tenantId(),h.projectId(),"DOCUMENT",h.documentId()),"field.confirm","DOCUMENT_BODY");}
 private static StrictFieldHumanBasis.Target target(String document,JsonNode n){return new StrictFieldHumanBasis.Target(document,text(n,"document_revision"),text(n,"field_id"),n.required("row_id").isNull()?null:text(n,"row_id"),text(n,"check_id"),n.required("strict_artifact_id").isNull()?null:text(n,"strict_artifact_id"));}
 private Map<String,Object> meta(EnterpriseAccess.Admission a,DocumentReadProtocol.Header h,LocalDateTime at){return new LinkedHashMap<>(Map.of("tenant_id",h.tenantId(),"project_id",h.projectId(),"created_by",a.actorId(),"created_at",at,"classification",h.classification(),"schema_version","1.0.0","schema_manifest_sha256",schema.manifest()));}
 private void insert(String table,Map<String,Object> values){var keys=new ArrayList<>(values.keySet());if(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(values::get).toArray())!=1)bad();}
 private static String id(){return UUID.randomUUID().toString();}private <T>T tx(ApplicationSessionIdentity.Verified s,Work<T> w){return access.execute(s,a->ThrowingSupplier.of(()->w.run(a)).get());}private interface Work<T>{T run(EnterpriseAccess.Admission a)throws Exception;}
}
